<script setup lang="ts">import {ref} from 'vue';import type {Corpus,Run,User} from '../types/domain';import {researchApi} from '../api/research';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import RunTable from '../components/RunTable.vue';const props=defineProps<{corpora:Corpus[];runs:Run[];user:User;reload:()=>Promise<any>}>();const emit=defineEmits<{select:[run:Run]}>();const corpus=ref(0),name=ref('四主题多初始化复核'),k=ref(4),repeats=ref(5),seed=ref(221),minDf=ref(2),maxIter=ref(2000),tol=ref(.0001);const {task,act}=useAsync();async function submit(){await act(async()=>{const r=await researchApi.queue({corpus_id:corpus.value||props.corpora[0]?.id,name:name.value,k:k.value,repeats:repeats.value,seed:seed.value,min_df:minDf.value,max_iter:maxIter.value,tolerance:tol.value});await props.reload();emit('select',r)},'主题分解已进入队列')};</script><template><PageTitle index="03 / PRESELECTED PROTOCOL" title="K先确定，重复才有比较基础。" description="K由编辑预先选择2–6；不把不同K误差随复杂度下降当自动最优。保存每次独立random初始化的完整分解与匹配。"/><div class="config-grid"><form class="editor" @submit.prevent="submit"><h2>建立可复算的主题方案</h2><fieldset :disabled="task.busy||user.role==='viewer'"><label>研究名称<input v-model="name" required maxlength="100"/></label><label>分词语料<select v-model="corpus"><option :value="0" v-if="corpora[0]">默认 / {{corpora[0].name}}</option><option v-for="c in corpora" :key="c.id" :value="c.id">{{c.name}} / {{c.document_count}}篇</option></select></label><div class="form-grid"><label>预选K<input type="number" v-model.number="k" min="2" max="6" step="1" required/></label><label>独立初始化次数<input type="number" v-model.number="repeats" min="5" max="10" step="1" required/></label><label>起始seed<input type="number" v-model.number="seed" min="0" max="1000000000" step="1" required/></label><label>最小文档频数min_df<input type="number" v-model.number="minDf" min="1" max="10" step="1" required/></label><label>迭代上限<input type="number" v-model.number="maxIter" min="10" max="3000" step="1" required/></label><label>收敛tolerance<input type="number" v-model.number="tol" min=".00000001" max=".01" step="any" required/></label></div><button class="primary" :disabled="!corpora.length">{{task.busy?'正在提交…':'提交TF-IDF与多次NMF →'}}</button></fieldset><p v-if="user.role==='viewer'">观察员可读主题册，提交需研究编辑权限。</p><Notice :error="task.error" :message="task.message"/></form><aside class="method-notes"><small>FIXED POLICY / 编辑口径</small><h2>每次重拟合，<br/>不只换个顺序。</h2><ol><li><b>固定词汇与TF-IDF</b><p>白名单精确空白切词，词汇从本语料拟合；raw TF、平滑idf、文档L2归一，保存vocabulary/idf。</p></li><li><b>独立NMF拟合</b><p>seed+i的random初始化，CD求非负分解。任一未收敛或空分量明确失败，不报伪稳定。</p></li><li><b>尺度与匹配</b><p>H行L1归一时W同步乘行范数保持WH；主题余弦经Hungarian对齐到首个预定重复。</p></li></ol><p class="fine">词权是非负表示，文档相对激活不是后验概率；初始化稳定不等于语义正确。</p></aside></div><div class="section-title"><h2>运行队列与主题册</h2><small>每3秒读取worker状态</small></div><RunTable :runs="runs" @select="emit('select',$event)"/></template>
